import EventEmitter from 'node:events';
import { inspect } from 'node:util';
function main(): void {
  const e: any = new EventEmitter();
  const f = () => {}; const g = () => {};
  e.on('a', f); console.log(typeof e._events.a, e._eventsCount);
  e.on('a', g); console.log(Array.isArray(e._events.a), e._events.a.length);
  e.once('b', f); console.log(typeof e._events.b, e._events.b.listener.name, e._eventsCount);
  console.log(e.listeners('b')[0].name, e.rawListeners('b')[0].name === 'f', e.eventNames());
  e.removeListener('a', f); console.log(e._events.a.name);
  e.off('a', g); console.log(Object.keys(e._events), e._eventsCount);
  console.log(inspect(new EventEmitter()));
  e.emit('b'); console.log(e.listenerCount('b'), e.getMaxListeners());
  try { e.on('x', 5 as any); } catch (err: any) { console.log(err.code, err.message); }
  try { e.setMaxListeners(-1); } catch (err: any) { console.log(err.code, err.message); }
  try { e.emit('error', new Error('boom')); } catch (err: any) { console.log(err.message); }
  try { e.emit('error', 'str'); } catch (err: any) { console.log(err.code, err.message); }
  const seen: string[] = [];
  e.on('newListener', (t: any) => seen.push('new:' + String(t)));
  e.on('removeListener', (t: any) => seen.push('rm:' + String(t)));
  e.on('z', f); e.once('z', g); e.removeAllListeners('z'); console.log(seen.join(','));
}
